/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::TransferOrderCreation)]
internal final class METTMSEngineTransferOrderProccess_Creation extends METTMSEngineOrderProccess
{
}

Method.Source:
/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineTransferOrderProcessCreation", headerContract.parmSourceRecord().OrderId);
}

/// <summary>
/// Sets the value for table buffer <t>METTMSShipmentTable</t>
/// </summary>
/// <param name = "_tmsShipmentTable">Record buffer of table <t>METTMSShipmentTable</t></param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    super(_tmsShipmentTable);

    _tmsShipmentTable.DestinationCustomer = METConstants::emptyString;
    _tmsShipmentTable.DestinationWarehouse = headerContract.parmSourceRecord().InventLocationTo;
}

/// <summary>
/// Get the execution mode enum value
/// </summary>
/// <returns>METTMSEngineExecutionMode</returns>
public METTMSEngineExecutionMode getExecutionMode()
{
    METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::TransferOrderCreation;

    return ret;
}
